class Peekable:
    def __init__(self, source):
        self.source = iter(source)
        self.buffer = []
    def __iter__(self):
        return self
    def __next__(self):
        if self.buffer:
            return self.buffer.pop()
        return next(self.source)
    def peek(self):
        if not self.buffer:
            self.buffer.append(next(self.source))
        return self.buffer[-1]

