def merge(a, b):
    it_a, it_b = iter(a), iter(b)
    head_a = next(it_a, None)
    head_b = next(it_b, None)
    while head_a is not None and head_b is not None:
        if head_a[0] <= head_b[0]:
            yield head_a
            head_a = next(it_a, None)
        else:
            yield head_b
            head_b = next(it_b, None)
    if head_a is not None:
        yield head_a
        yield from it_a
    if head_b is not None:
        yield head_b
        yield from it_b

