from itertools import count, islice

class PullLimitExceeded(Exception):
    pass

def guarded(stream, limit):
    pulls = 0
    for item in stream:
        pulls += 1
        if pulls > limit:
            raise PullLimitExceeded(f"over {limit} pulls and still hungry")
        yield item

